1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
26	
27	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	  moonstone: 25,
34	};
35	
36	const basePremiumOf = (itemType: string): number =>
37	  BASE_PREMIUM_BY_ITEM_TYPE[itemType];
38	
39	const COMPONENT_BLOCK_SIZE = 3;
40	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
41	
42	const countByItemType = (items: Item[]): Map<string, number> =>
43	  items.reduce(
44	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
45	    new Map<string, number>(),
46	  );
47	
48	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
49	
50	const isComponent = (itemType: string): boolean =>
51	  COMPONENT_TYPES.has(itemType);
52	
53	const basePremiumForCountOf = (itemType: string, count: number): number =>
54	  isComponent(itemType) && count === COMPONENT_BLOCK_SIZE
55	    ? COMPONENT_BLOCK_BASE_PREMIUM
56	    : count * basePremiumOf(itemType);
57	
58	const sum = (amounts: number[]): number =>
59	  amounts.reduce((total, amount) => total + amount, 0);
60	
61	const policyBasePremiumOf = (items: Item[]): number =>
62	  sum(
63	    [...countByItemType(items)].map(([itemType, count]) =>
64	      basePremiumForCountOf(itemType, count),
65	    ),
66	  );
67	
68	const CURSE_SURCHARGE_PERCENT = 50;
69	
70	const itemSurchargesOf = (items: Item[]): number =>
71	  sum(
72	    items.map((item) =>
73	      item.cursed
74	        ? (basePremiumOf(item.type) * CURSE_SURCHARGE_PERCENT) / 100
75	        : 0,
76	    ),
77	  );
78	
79	const quotePremium = (items: Item[]): number => {
80	  const policyBasePremium = policyBasePremiumOf(items);
81	  const firstInsuranceSurcharge =
82	    (policyBasePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
83	
84	  return Math.ceil(
85	    policyBasePremium +
86	      itemSurchargesOf(items) +
87	      firstInsuranceSurcharge +
88	      PROCESSING_FEE,
89	  );
90	};
91	
92	export const runScenario = (scenario: Scenario): StepResult[] =>
93	  scenario.steps.map((step) => {
94	    if (step.op === "quote") return { premium: quotePremium(step.items) };
95	    throw new Error(`Unsupported step: ${step.op}`);
96	  });
